/**
 * Removes every comment document on one issue. Scoped by org and issue, so a
 * sibling issue or another workspace is left untouched. Pages through the
 * thread so a long discussion is fully removed, replies included.
 */
async function removeCommentsOnIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: true,
      limit: COMMENT_PAGE_SIZE,
      cursor,
    });
    for (const comment of page.items) {
      await removeFromIndex(orgId, "comment", comment.id);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

