/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import { isLive } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. Repositories cap a page at this size. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Follows `nextCursor` until the repository reports no further page, so a
 * workspace larger than one page is fully visited.
 */
async function forEachPage<T>(
  fetchPage: (
    cursor: string | null,
  ) => Promise<{ items: readonly T[]; nextCursor: string | null }>,
  handle: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      await handle(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/**
 * Walks one tenant's live projects, non-archived issues and the non-deleted
 * comments on those issues, and re-upserts every document. A live reply whose
 * parent comment was deleted is included. Scoped to a single org on purpose:
 * a full-fleet reindex is a sequence of these, so one slow tenant cannot
 * stall the rest.
 *
 * The previous index for this org is dropped first. That clears archived
 * issues, deleted comments and comments left behind on archived issues, and
 * a second run cannot insert a duplicate of a row that is about to be rewritten.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteOrgSearchDocuments(orgId);

    await forEachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
        }),
      async (project) => {
        if (!isLive(project)) return;
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (issue) => {
        if (!isLive(issue)) return;
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          return;
        }

        await forEachPage(
          (cursor) =>
            commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: false,
              limit: PAGE_SIZE,
              cursor,
            }),
          async (comment) => {
            if (!isLive(comment)) return;
            try {
              await indexComment(orgId, comment);
              result.processed += 1;
            } catch (error) {
              result.failed += 1;
              logger.error("failed to index comment", {
                commentId: comment.id,
                reason: error instanceof Error ? error.message : String(error),
              });
            }
          },
        );
      },
    );
  });
}

