import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("reindex-fix", "growth");
  other = await createTenant("reindex-other", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

async function hits(orgId: Tenant["org"]["id"], actor: Tenant["actors"]["member"], q: string, kinds: Array<"issue" | "comment" | "project">) {
  const page = await searchService.search(actor, {
    orgId,
    q,
    kinds,
    limit: 25,
    cursor: null,
  });
  return page.total;
}

describe("deleted comments, archived issues, and rebuild", () => {
  it("counts only live comments, including replies", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Count carrier" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "parent stays",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "reply stays",
      parentId: parent.id,
      mentionedUserIds: [],
    });
    const doomed = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "doomed count",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: doomed.id,
    });

    const loaded = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(loaded.commentCount).toBe(2);
    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(2);
  });

  it("drops only the deleted comment from search", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "DeleteIndexIssueMarker" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "DeleteIndexParentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "DeleteIndexReplyMarker",
      parentId: parent.id,
      mentionedUserIds: [],
    });

    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: parent.id,
    });

    expect(await hits(tenant.org.id, tenant.actors.member, "DeleteIndexParentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "DeleteIndexReplyMarker", ["comment"])).toBe(1);
    expect(await hits(tenant.org.id, tenant.actors.member, "DeleteIndexIssueMarker", ["issue"])).toBe(1);
  });

  it("drops an archived issue and its comments only", async () => {
    const kept = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "KeptIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "KeptCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    const archived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchivedIssueMarker" }),
    );
    const top = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: archived.id,
      body: "ArchivedCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: archived.id,
      body: "ArchivedReplyMarker",
      parentId: top.id,
      mentionedUserIds: [],
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    expect(await hits(tenant.org.id, tenant.actors.member, "ArchivedIssueMarker", ["issue"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "ArchivedCommentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "ArchivedReplyMarker", ["comment"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "KeptIssueMarker", ["issue"])).toBe(1);
    expect(await hits(tenant.org.id, tenant.actors.member, "KeptCommentMarker", ["comment"])).toBe(1);
  });

  it("rebuilds every live issue and comment once, and nothing stale", async () => {
    const oldest = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "OldestIssueMarker" }),
    );
    const threadParent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: oldest.id,
      body: "DeletedParentButReplyLivesMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: oldest.id,
      body: "EarliestCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: oldest.id,
      body: "LiveReplyUnderDeletedMarker",
      parentId: threadParent.id,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: threadParent.id,
    });

    for (let i = 0; i < 130; i += 1) {
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: oldest.id,
        body: `filler-comment-${i}`,
        parentId: null,
        mentionedUserIds: [],
      });
    }

    for (let i = 0; i < 120; i += 1) {
      await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: `filler-issue-${i}` }),
      );
    }

    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "ForeignIssueMarker" }),
    );
    await commentService.createComment(other.actors.member, {
      orgId: other.org.id,
      issueId: foreign.id,
      body: "ForeignCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    const beforeOther = await searchRepo.countIndexed(other.org.id);

    await runSearchReindexJob(tenant.org.id);
    const once = await searchRepo.countIndexed(tenant.org.id);
    await runSearchReindexJob(tenant.org.id);
    const twice = await searchRepo.countIndexed(tenant.org.id);

    expect(twice).toBe(once);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(beforeOther);
    expect(await hits(tenant.org.id, tenant.actors.member, "OldestIssueMarker", ["issue"])).toBe(1);
    expect(await hits(tenant.org.id, tenant.actors.member, "EarliestCommentMarker", ["comment"])).toBe(1);
    expect(await hits(tenant.org.id, tenant.actors.member, "LiveReplyUnderDeletedMarker", ["comment"])).toBe(1);
    expect(await hits(tenant.org.id, tenant.actors.member, "DeletedParentButReplyLivesMarker", ["comment"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "ArchivedIssueMarker", ["issue"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "ArchivedCommentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant.org.id, tenant.actors.member, "ForeignIssueMarker", ["issue"])).toBe(0);
    expect(await hits(other.org.id, other.actors.member, "ForeignIssueMarker", ["issue"])).toBe(1);
    expect(await hits(other.org.id, other.actors.member, "ForeignCommentMarker", ["comment"])).toBe(1);
  });
});

